class Solution {
public:
    vector<string> findHighAccessEmployees(vector<vector<string>>& access_times) {
        unordered_map<string, vector<int>> groups;
        for (const auto& entry : access_times) {
            int mins = stoi(entry[1].substr(0, 2)) * 60 + stoi(entry[1].substr(2, 2));
            groups[entry[0]].push_back(mins);
        }
        vector<string> ans;
        for (auto& [name, times] : groups) {
            sort(times.begin(), times.end());
            for (int i = 0; i + 2 < times.size(); i++) {
                if (times[i + 2] - times[i] < 60) {
                    ans.push_back(name);
                    break;
                }
            }
        }
        return ans;
    }
};

class Solution {
    public List<String> findHighAccessEmployees(List<List<String>> access_times) {
        Map<String, List<Integer>> groups = new HashMap<>();
        for (List<String> entry : access_times) {
            String name = entry.get(0);
            String t = entry.get(1);
            int mins = Integer.parseInt(t.substring(0, 2)) * 60 + Integer.parseInt(t.substring(2, 4));
            groups.computeIfAbsent(name, k -> new ArrayList<>()).add(mins);
        }
        List<String> ans = new ArrayList<>();
        for (Map.Entry<String, List<Integer>> entry : groups.entrySet()) {
            List<Integer> times = entry.getValue();
            Collections.sort(times);
            for (int i = 0; i + 2 < times.size(); i++) {
                if (times.get(i + 2) - times.get(i) < 60) {
                    ans.add(entry.getKey());
                    break;
                }
            }
        }
        return ans;
    }
}

/**
 * @param {string[][]} access_times
 * @return {string[]}
 */
var findHighAccessEmployees = function(access_times) {
    const groups = new Map();
    for (const [name, t] of access_times) {
        const mins = parseInt(t.slice(0, 2), 10) * 60 + parseInt(t.slice(2, 4), 10);
        if (!groups.has(name)) groups.set(name, []);
        groups.get(name).push(mins);
    }
    const ans = [];
    for (const [name, times] of groups.entries()) {
        times.sort((a, b) => a - b);
        for (let i = 0; i + 2 < times.length; i++) {
            if (times[i + 2] - times[i] < 60) {
                ans.push(name);
                break;
            }
        }
    }
    return ans;
};
